#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "clip_hierarchy.h"
#include "graph_transform_hierarchy.h"
int main(){try{Graph g;g.strings={"DmeDag","DmeTransform","root","child","transform","children","position","orientation","scale"};g.elements.resize(4);g.elements[0].type=0;g.elements[0].name=2;g.elements[1].type=1;g.elements[1].name=2;g.elements[2].type=0;g.elements[2].name=3;g.elements[3].type=1;g.elements[3].name=3;
 auto reference=[](uint32_t name,uint8_t type,uint32_t target){Value v;v.reference=target;return Attribute{name,type,{v}};};g.elements[0].attributes={reference(4,1,1),reference(5,15,2)};g.elements[2].attributes={reference(4,1,3)};
 auto numeric=[](uint32_t name,uint8_t type,std::initializer_list<float>numbers){Value v;v.wire.resize(numbers.size()*4);size_t offset=0;for(float n:numbers){std::memcpy(v.wire.data()+offset,&n,4);offset+=4;}return Attribute{name,type,{v}};};g.elements[1].attributes={numeric(6,10,{10,0,0}),numeric(7,13,{0,0,0,1}),numeric(8,3,{2})};g.elements[3].attributes={numeric(6,10,{3,0,0}),numeric(7,13,{0,0,0,1}),numeric(8,3,{4})};
 auto local=graphLocalTransformMatrix(g,1,true);if(local[0][0]!=2||local[0][3]!=10)throw std::runtime_error("local basis/translation mismatch");if(graphLocalTransformMatrix(g,1)[0][0]!=1)throw std::runtime_error("bone caller scaled twice");GraphTransformHierarchy hierarchy(g);auto world=hierarchy.world(2);if(world[0][0]!=8||world[1][1]!=8||world[2][2]!=8||world[0][3]!=16)throw std::runtime_error("scaled parent/child composition mismatch");const float half=std::sqrt(0.5f);g.elements[1].attributes[1]=numeric(7,13,{0,0,half,half});GraphTransformHierarchy rotated(g);auto rotatedWorld=rotated.world(2);if(std::fabs(rotatedWorld[0][3]-10.f)>0.00001f||std::fabs(rotatedWorld[1][3]-6.f)>0.00001f)throw std::runtime_error("rotated scaled translation mismatch");auto orientation=rotated.worldOrientation(2);if(std::fabs(std::fabs(orientation[2])-half)>0.00001f||std::fabs(std::fabs(orientation[3])-half)>0.00001f||std::fabs(orientation[0])>0.00001f||std::fabs(orientation[1])>0.00001f)throw std::runtime_error("scale leaked into orientation");setFloat(g.elements[1].attributes[2],0,INFINITY);bool rejected=false;try{GraphTransformHierarchy invalid(g);invalid.world(2);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("nonfinite scale accepted");std::cout<<"hierarchy_scale_checks=6 translation_preserved parent_child_composed separate_bone_scale nonfinite_rejected rotated_translation scale_free_orientation\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
